Hello team! 👋 Here is my reasoning before the code. I'll split both strings on "/" into segments, then match them recursively with memoisation. A "**" segment can absorb zero or more whole path segments, so it tries every split point. Any other pattern segment must match exactly one path segment, with "*" and "?" applied only within that segment, so they can never cross a "/". The empty path has one empty segment, and "**" matches it because it can absorb zero segments. I'll use `functools.lru_cache` to keep the search polynomial, and avoid recursion depth problems by bounding the work to segment counts. 🚀

```python
from functools import lru_cache


def _seg_match(pat: str, seg: str) -> bool:
    # Match one pattern segment (no "**") against one path segment.
    # "*" matches any run (possibly empty) within the segment; "?" one char.
    # Neither can cross "/" because segments contain no "/".
    p_len, s_len = len(pat), len(seg)
    # dp[j] = pat[:i] matches seg[:j]
    dp = [False] * (s_len + 1)
    dp[0] = True
    for i in range(p_len):
        c = pat[i]
        new = [False] * (s_len + 1)
        if c == "*":
            # "*" matches empty, or extends any prefix match by one char
            seen = False
            for j in range(s_len + 1):
                seen = seen or dp[j]
                new[j] = seen
        else:
            for j in range(1, s_len + 1):
                if dp[j - 1] and (c == "?" or c == seg[j - 1]):
                    new[j] = True
        dp = new
    return dp[s_len]


def glob_match(pattern: str, path: str) -> bool:
    pat_segs = tuple(pattern.split("/"))
    path_segs = tuple(path.split("/"))
    n_pat = len(pat_segs)
    n_path = len(path_segs)

    @lru_cache(maxsize=None)
    def go(i: int, j: int) -> bool:
        # Can pat_segs[i:] match path_segs[j:]?
        if i == n_pat:
            return j == n_path
        if pat_segs[i] == "**":
            # Absorb zero or more whole segments.
            if go(i + 1, j):
                return True
            return j < n_path and go(i, j + 1)
        if j == n_path:
            return False
        if not _seg_match(pat_segs[i], path_segs[j]):
            return False
        return go(i + 1, j + 1)

    return go(0, 0)
