            out.append("")
        words = " ".join(para_lines).split()

        line = ""
        for word in words:
            if len(word) > width:
                # Flush the current line before a long word.
                if line:
                    out.append(line)
                    line = ""
                # Cut the long word into pieces of exactly `width`.
                pieces = [word[i:i + width] for i in range(0, len(word), width)]
                for piece in pieces[:-1]:
